/// <reference lib="webworker" />

import { FFmpeg } from '@ffmpeg/ffmpeg';
import { toBlobURL } from '@ffmpeg/util';

// eslint-disable-next-line no-restricted-globals
const ctx = self as unknown as DedicatedWorkerGlobalScope;

let ffmpeg: FFmpeg | null = null;
let hldspModule: {
  FS: {
    writeFile: (path: string, data: Uint8Array) => void;
    readFile: (path: string) => Uint8Array;
    unlink: (path: string) => void;
  };
  _hldsp_process: (roomIndex: number) => number;
} | null = null;
let basePath = '/';
let busy = false;

async function createHLDSPWrapper(opts: { locateFile: (path: string) => string }) {
  const response = await fetch(basePath + 'hldsp.js');
  const code = await response.text();
  const factory = new Function(code + '\nreturn createHLDSP;')();
  return factory(opts);
}

async function loadModules() {
  ctx.postMessage({ type: 'loading', message: 'Loading FFmpeg modules...' });

  ffmpeg = new FFmpeg();
  ffmpeg.on('log', ({ message }) => {
    ctx.postMessage({ type: 'log', message });
  });

  const coreURL = 'https://unpkg.com/@ffmpeg/core@0.12.10/dist/umd';
  await ffmpeg.load({
    coreURL: await toBlobURL(`${coreURL}/ffmpeg-core.js`, 'text/javascript'),
    wasmURL: await toBlobURL(`${coreURL}/ffmpeg-core.wasm`, 'application/wasm'),
  });

  ctx.postMessage({ type: 'loading', message: 'Loading HLDSP module...' });

  hldspModule = await createHLDSPWrapper({
    locateFile: (path: string) => basePath + path,
  });
}

ctx.onmessage = async (e: MessageEvent) => {
  const data = e.data;

  if (data.type === 'load') {
    basePath = data.basePath || '/';
    try {
      await loadModules();
      ctx.postMessage({ type: 'loaded' });
    } catch (err) {
      ctx.postMessage({ type: 'error', message: err instanceof Error ? err.message : 'Failed to load modules' });
    }
    return;
  }

  if (data.type === 'process') {
    if (busy) return;
    busy = true;

    try {
      const { file, fileName, format, bitrate, roomType } = data;
      const inputData = new Uint8Array(file);
      const baseName = fileName.replace(/\.[^.]+$/, '');
      const outputFileName = `${baseName}-hldsp.${format.extension}`;

      ctx.postMessage({ type: 'step', step: 'wav', snackbar: 'Converting audio to intermediate format...' });
      await ffmpeg!.writeFile(fileName, inputData);
      await ffmpeg!.exec(['-i', fileName, '-c:a', 'pcm_s16le', '-ar', '44100', '-ac', '2', 'temp.wav']);
      const wavData = await ffmpeg!.readFile('temp.wav') as Uint8Array;

      ctx.postMessage({ type: 'step', step: 'dsp', snackbar: `Applying DSP effects (preset: ${roomType.title})...` });
      hldspModule!.FS.writeFile('/input.wav', wavData);
      const result = hldspModule!._hldsp_process(roomType.index);
      if (result !== 0) {
        hldspModule!.FS.unlink('/input.wav');
        throw new Error('DSP processing failed.');
      }
      const processedWav = hldspModule!.FS.readFile('/output.wav');
      hldspModule!.FS.unlink('/input.wav');
      hldspModule!.FS.unlink('/output.wav');

      ctx.postMessage({ type: 'step', step: 'encode', snackbar: `Converting audio to ${format.title} format...` });
      await ffmpeg!.writeFile('processed.wav', processedWav);
      await ffmpeg!.exec(['-i', 'processed.wav', '-c:a', format.codec, '-b:a', bitrate.value, outputFileName]);
      const outputData = await ffmpeg!.readFile(outputFileName) as Uint8Array;

      try { await ffmpeg!.deleteFile(fileName) } catch { /* ignore */ }
      try { await ffmpeg!.deleteFile('temp.wav') } catch { /* ignore */ }
      try { await ffmpeg!.deleteFile('processed.wav') } catch { /* ignore */ }
      try { await ffmpeg!.deleteFile(outputFileName) } catch { /* ignore */ }

      ctx.postMessage({ type: 'result', data: outputData.buffer as ArrayBuffer, fileName: outputFileName }, [outputData.buffer]);
    } catch (err) {
      ctx.postMessage({ type: 'error', message: err instanceof Error ? err.message : 'Processing failed.' });
    } finally {
      busy = false;
    }
    return;
  }
};
